const form=document.querySelector('#impact-publish'),feedback=document.querySelector('#impact-feedback'),period=document.querySelector('#publish-period');let records=[];
async function refresh(){const response=await fetch('/api/impacto');if(!response.ok)throw Error('Não foi possível consultar as publicações.');records=(await response.json()).periodos.filter(r=>r.publicada!==false);document.querySelector('#impact-published-count').textContent=records.length+' período(s) publicado(s). Para corrigir, carregue o mês e publique os novos valores; a publicação substitui o mês, sem duplicar os números.';const select=document.querySelector('#published-periods');select.replaceChildren(new Option('Escolha um período publicado',''));for(const r of records)select.add(new Option(r.periodo,r.periodo));}
document.querySelector('#published-periods').onchange=e=>{const r=records.find(x=>x.periodo===e.target.value);if(!r)return;for(const k of ['periodo','pessoas','familias','atendimentos','cestas','voluntarios','fonte'])if(form.elements[k])form.elements[k].value=(r.base&&['pessoas','atendimentos','cestas','voluntarios'].includes(k))?r.base[k]:r[k];form.elements.parceiros.value=r.parceiros.join('\n');form.elements.confirmado.checked=false;};
form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button[type=submit]');button.disabled=true;feedback.textContent='Publicando…';const f=new FormData(form),data={periodo:f.get('periodo'),fonte:f.get('fonte'),parceiros:String(f.get('parceiros')||'').split('\n').map(v=>v.trim()).filter(Boolean),confirmado:f.get('confirmado')==='on',acoes:0};for(const key of ['pessoas','familias','atendimentos','cestas','voluntarios'])data[key]=Number(f.get(key));try{const response=await fetch('/api/admin/impacto',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),r=await response.json();if(!response.ok)throw Error(r.error);await refresh();const saved=records.find(r=>r.periodo===data.periodo);if(!saved||['pessoas','familias','atendimentos','cestas','voluntarios'].some(k=>(saved.base&&['pessoas','atendimentos','cestas','voluntarios'].includes(k)?saved.base[k]:saved[k])!==data[k]))throw Error('Não foi possível confirmar os valores publicados. Recarregue antes de tentar novamente.');feedback.replaceChildren(document.createTextNode('Publicação conferida: '+data.pessoas+' pessoa(s) alcançada(s), '+data.familias+' família(s) e '+data.atendimentos+' atendimento(s) em '+data.periodo+'. '));const link=document.createElement('a');link.href='/impacto?periodo='+encodeURIComponent(data.periodo);link.target='_blank';link.rel='noopener';link.textContent='Ver este mês no dashboard público ↗';feedback.append(link);document.querySelector('#published-periods').value=data.periodo;window.dispatchEvent(new CustomEvent('admin-data-updated',{detail:{periodo:data.periodo}}));}catch(e){feedback.textContent=e.message||'Não foi possível publicar.';}finally{button.disabled=false;}};
document.querySelector('#impact-withdraw').onclick=async()=>{if(!period.value)return;try{const response=await fetch('/api/admin/impacto/remover',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({periodo:period.value})});if(!response.ok)throw Error('Não foi possível retirar a publicação.');feedback.textContent='Publicação retirada do painel público.';await refresh();window.dispatchEvent(new CustomEvent('admin-data-updated',{detail:{periodo:period.value}}));}catch(e){feedback.textContent=e.message;}};period.max=new Date().toISOString().slice(0,7);refresh().catch(e=>feedback.textContent=e.message);
